import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Cs11k9ph.js";const u=JSON.parse('{"title":"📡 API 参考（v3.2）","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":1788080140000}'),r={name:"api.md"};function c(i,t,h,s,n,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="📡-api-参考-v3-2" tabindex="-1">📡 API 参考（v3.2） <a class="header-anchor" href="#📡-api-参考-v3-2" aria-label="Permalink to &quot;📡 API 参考（v3.2）&quot;">​</a></h1><blockquote><p>本文档对应 <strong>AgoraIn v3.2</strong> 集控服务器。旧版 v2.7 文档已归档：<a href="/v2.7/api.html">v2.7 API 文档</a>。</p></blockquote><p>所有接口返回 JSON。非登录接口需携带服务器密码（<code>ServerPassword</code>）校验，管理类接口需 JWT 令牌。</p><hr><h2 id="基础信息" tabindex="-1">基础信息 <a class="header-anchor" href="#基础信息" aria-label="Permalink to &quot;基础信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>服务器</td><td>ASP.NET Core + EF Core + SQLite</td></tr><tr><td>默认端口</td><td>5250（<code>config.json</code> 可改）</td></tr><tr><td>数据格式</td><td>JSON</td></tr><tr><td>认证</td><td>服务器密码 / JWT 令牌</td></tr></tbody></table><hr><h2 id="端点一览" tabindex="-1">端点一览 <a class="header-anchor" href="#端点一览" aria-label="Permalink to &quot;端点一览&quot;">​</a></h2><h3 id="状态与版本" tabindex="-1">状态与版本 <a class="header-anchor" href="#状态与版本" aria-label="Permalink to &quot;状态与版本&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/status</code></td><td>服务器状态与设备/任务统计</td></tr><tr><td><code>GET /api/version</code></td><td>服务器版本号</td></tr><tr><td><code>GET /api/server_update</code></td><td>集控平台新版本检查（后台轮询 GitHub）</td></tr></tbody></table><h3 id="设备管理" tabindex="-1">设备管理 <a class="header-anchor" href="#设备管理" aria-label="Permalink to &quot;设备管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/register</code></td><td>设备注册</td></tr><tr><td><code>GET /api/machines/{uuid}/tasks</code></td><td>获取设备关联任务</td></tr><tr><td><code>POST /api/delete_machine</code></td><td>删除设备</td></tr></tbody></table><h3 id="数据同步" tabindex="-1">数据同步 <a class="header-anchor" href="#数据同步" aria-label="Permalink to &quot;数据同步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/sync_data</code></td><td>打卡数据同步</td></tr><tr><td><code>POST /api/load_data</code></td><td>从服务器加载数据</td></tr></tbody></table><h3 id="配置管理" tabindex="-1">配置管理 <a class="header-anchor" href="#配置管理" aria-label="Permalink to &quot;配置管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/get_config</code></td><td>获取服务器配置</td></tr><tr><td><code>POST /api/update_config</code></td><td>更新服务器配置（版本号 +1，触发客户端推送）</td></tr><tr><td><code>POST /api/update_machine_config</code></td><td>更新设备配置</td></tr><tr><td><code>POST /api/config_applied</code></td><td>客户端确认配置已应用</td></tr></tbody></table><h3 id="打卡与考勤" tabindex="-1">打卡与考勤 <a class="header-anchor" href="#打卡与考勤" aria-label="Permalink to &quot;打卡与考勤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/web_punch</code></td><td>Web 端打卡</td></tr><tr><td><code>POST /api/web_cancel_punch</code></td><td>Web 端取消打卡</td></tr><tr><td><code>POST /api/clear_attendance</code></td><td>清空考勤记录</td></tr></tbody></table><h3 id="签到任务" tabindex="-1">签到任务 <a class="header-anchor" href="#签到任务" aria-label="Permalink to &quot;签到任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/create_signin</code></td><td>创建签到任务（短码 + 密码 + 教室/科目）</td></tr><tr><td><code>POST /api/signin_result</code></td><td>签到结果回写</td></tr></tbody></table><h3 id="用户与认证" tabindex="-1">用户与认证 <a class="header-anchor" href="#用户与认证" aria-label="Permalink to &quot;用户与认证&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET/POST /api/users</code></td><td>用户列表 / 创建用户</td></tr><tr><td><code>POST /api/users/change-password</code></td><td>修改密码</td></tr><tr><td><code>POST /api/auth/login</code></td><td>管理员登录（JWT）</td></tr><tr><td><code>POST /api/auth/verify</code></td><td>验证令牌</td></tr></tbody></table><h3 id="二维码签到" tabindex="-1">二维码签到 <a class="header-anchor" href="#二维码签到" aria-label="Permalink to &quot;二维码签到&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>POST /api/qrcode/generate</code></td><td>生成签到二维码</td></tr><tr><td><code>POST /api/qrcode/checkin</code></td><td>扫码签到</td></tr></tbody></table><h3 id="移动端-api" tabindex="-1">移动端 API <a class="header-anchor" href="#移动端-api" aria-label="Permalink to &quot;移动端 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/mobile/dashboard</code></td><td>管理员仪表盘</td></tr><tr><td><code>GET /api/mobile/attendance</code></td><td>考勤记录</td></tr><tr><td><code>GET /api/mobile/tasks</code>、<code>POST /api/mobile/tasks/{id}/close</code></td><td>任务列表 / 关闭任务</td></tr><tr><td><code>GET /api/mobile/tasks/{id}/qrcode</code></td><td>任务二维码</td></tr><tr><td><code>GET /api/mobile/devices</code>、<code>POST /api/mobile/devices/{uuid}/tasks</code></td><td>设备列表 / 设备分配任务</td></tr><tr><td><code>GET /api/mobile/students/history</code></td><td>学生打卡历史</td></tr><tr><td><code>GET/POST /api/mobile/assignments</code></td><td>排课（设备分配）管理</td></tr><tr><td><code>GET /api/mobile/teachers</code></td><td>教师列表</td></tr></tbody></table><h3 id="调试接口" tabindex="-1">调试接口 <a class="header-anchor" href="#调试接口" aria-label="Permalink to &quot;调试接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/debug/status</code>、<code>/api/debug/token</code>、<code>POST /api/debug/login</code></td><td>调试模式（<code>DebugMode: true</code> 时生效）</td></tr></tbody></table><hr><h2 id="认证机制" tabindex="-1">认证机制 <a class="header-anchor" href="#认证机制" aria-label="Permalink to &quot;认证机制&quot;">​</a></h2><h3 id="服务器密码校验" tabindex="-1">服务器密码校验 <a class="header-anchor" href="#服务器密码校验" aria-label="Permalink to &quot;服务器密码校验&quot;">​</a></h3><p>非登录接口需在请求中携带服务器密码（<code>config.json</code> 中的 <code>ServerPassword</code>）。</p><h3 id="jwt-令牌" tabindex="-1">JWT 令牌 <a class="header-anchor" href="#jwt-令牌" aria-label="Permalink to &quot;JWT 令牌&quot;">​</a></h3><p>管理类接口（Web 管理面板、移动端管理员）通过登录获取 JWT 令牌：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST /api/auth/login</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;********&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>响应中返回 <code>token</code>，后续请求在 <code>Authorization: Bearer &lt;token&gt;</code> 头中携带。</p><h3 id="密码哈希" tabindex="-1">密码哈希 <a class="header-anchor" href="#密码哈希" aria-label="Permalink to &quot;密码哈希&quot;">​</a></h3><p>用户密码采用<strong>加盐 SHA256</strong> 哈希存储；管理员密码通过 SHA256 哈希校验。</p><hr><h2 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to &quot;配置说明&quot;">​</a></h2><h3 id="服务器-config-json" tabindex="-1">服务器 <code>config.json</code> <a class="header-anchor" href="#服务器-config-json" aria-label="Permalink to &quot;服务器 `config.json`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>Port</code></td><td><code>5250</code></td><td>监听端口</td></tr><tr><td><code>ServerName</code></td><td><code>&quot;&quot;</code></td><td>服务器名称</td></tr><tr><td><code>ServerPassword</code></td><td><code>&quot;&quot;</code></td><td>服务器连接密码（首次运行自动生成）</td></tr><tr><td><code>DebugMode</code></td><td><code>false</code></td><td>调试模式开关</td></tr></tbody></table><h3 id="客户端-config-json-全局配置" tabindex="-1">客户端 <code>config.json</code>（全局配置） <a class="header-anchor" href="#客户端-config-json-全局配置" aria-label="Permalink to &quot;客户端 `config.json`（全局配置）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>School</code></td><td><code>&quot;&quot;</code></td><td>学校名称</td></tr><tr><td><code>Nj</code></td><td><code>&quot;&quot;</code></td><td>年级（年份）</td></tr><tr><td><code>ClassId</code></td><td><code>&quot;&quot;</code></td><td>班级编号</td></tr><tr><td><code>Km</code></td><td><code>&quot;&quot;</code></td><td>课程名称（如&quot;数学&quot;）</td></tr><tr><td><code>ButtonRows</code></td><td><code>6</code></td><td>学生按钮网格行数</td></tr><tr><td><code>ButtonCols</code></td><td><code>6</code></td><td>学生按钮网格列数</td></tr><tr><td><code>OnlineMode</code></td><td><code>true</code></td><td>是否启用在线模式</td></tr><tr><td><code>ServerIp</code></td><td><code>&quot;&quot;</code></td><td>远程服务器 IP</td></tr><tr><td><code>ServerPort</code></td><td><code>5250</code></td><td>远程服务器端口</td></tr><tr><td><code>ServerPassword</code></td><td><code>&quot;&quot;</code></td><td>远程服务器连接密码</td></tr><tr><td><code>AdminPasswordHash</code></td><td><code>&quot;&quot;</code></td><td>管理员密码 SHA256 哈希（空表示无密码）</td></tr></tbody></table><h3 id="课时数据-data-classhours-json-版本-v3" tabindex="-1">课时数据 <code>data/classhours.json</code>（版本 v3） <a class="header-anchor" href="#课时数据-data-classhours-json-版本-v3" aria-label="Permalink to &quot;课时数据 `data/classhours.json`（版本 v3）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>Version</code></td><td>数据版本号（v3：排课细分时间 + 自动划消设置）</td></tr><tr><td><code>Students</code></td><td>学生列表（姓名、总课时、已划课时、备注、创建时间）</td></tr><tr><td><code>Records</code></td><td>课时记录流水（日期、课时数正负、备注、SlotKey 去重键）</td></tr><tr><td><code>Schedule</code></td><td>排课数据：日期 → 排课条目（学生 + 上课/下课时间，支持跨天）</td></tr><tr><td><code>OffDays</code></td><td>不排课日集合</td></tr><tr><td><code>HoursPerHour</code></td><td>每小时上课消耗课时（支持小数，默认 1）</td></tr><tr><td><code>AutoDeduct</code></td><td>是否自动划消课时</td></tr></tbody></table>',46)])])}const p=d(r,[["render",c]]);export{u as __pageData,p as default};
